import currency
I = importlib

#distribute TAU to a list of addresses with same amounts
@export
def distr_same(addresses: list, amount: float):
    for address in addresses:
        assert len(address) == 64, f"Address no. {addresses.index(address)+1} is not 64 in length"
        currency.transfer_from(amount=amount, to=address, main_account=ctx.signer)

#distribute TAU to a list of addresses with varying amounts     
@export
def distr_var(addresses: list, amounts: list):
    for num in range(len(addresses)):
        address = addresses[num]
        amount = amounts[num]
        assert len(address) == 64, f"Address no. {addresses.index(address)+1} is not 64 in length"
        currency.transfer_from(amount=amount, to=address, main_account=ctx.signer)

#distribute any token to a list of addresses with same amounts 
@export
def distr_token_same(token: str, addresses: list, amount: float):
    for address in addresses:
        asset = I.import_module(token)
        assert len(address) == 64, f"Address no. {addresses.index(address)+1} is not 64 in length"
        asset.transfer_from(amount=amount, to=address, main_account=ctx.signer)

#distribute any token to a list of addresses with varying amounts  
@export
def distr_token_var(token: str, addresses: list, amounts: list):
    for num in range(len(addresses)):
        address = addresses[num]
        amount = amounts[num]
        asset = I.import_module(token)
        assert len(address) == 64, f"Address no. {addresses.index(address)+1} is not 64 in length"
        asset.transfer_from(amount=amount, to=address, main_account=ctx.signer)
